import nav_model


def render(tabs, active):
    links = "".join(
        f'<a href="#{t["id"]}" class="tab">{t["label"]}</a>' for t in nav_model.items(tabs, active))
    return f"<nav>{links}</nav>"


def preview():
    return render([("mission", "Mission"), ("arena", "Arena"), ("proof", "Proof")], "arena")
